import { PromiseToast } from "@/components/design-for-ai/toast-promise";

// Fills the nearest positioned parent, so give that parent a height (use strategy="fixed" to pin it to the viewport).
<div className="relative h-40">
  <PromiseToast
    job={() => api.threads.archive(ids)}
    loadingTitle="Archiving 12 threads…"
    successTitle="Archived 12 threads"
    errorTitle="Couldn’t archive 12 threads"
    undoTitle="Restored 12 threads"
    onUndo={() => api.threads.restore(ids)}
    onRetry={() => trackRetry(ids)}
  />
</div>

// Run the job again by changing runKey, for example a new batch id.
<PromiseToast job={submit} runKey={batchId} position="bottom-center" duration={8} />

// undo={false}: success still leaves after duration, just without the Undo button and ring.
